using BARANG.Core.Domain.Security;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class OrderConfig
{
 internal static void Company<T>(EntityTypeBuilder<T>b,string table)where T:class{b.ToTable(table);b.HasKey("Id").HasName($"pk_{table}");b.Property<Guid>("Id").HasColumnName("id").ValueGeneratedNever();b.Property<Guid>("CompanyId").HasColumnName("company_id");b.HasAlternateKey("CompanyId","Id").HasName($"ak_{table}_company_id_id");b.HasOne<Company>().WithMany().HasForeignKey("CompanyId").OnDelete(DeleteBehavior.Restrict);}
 internal static void Mutable<T>(EntityTypeBuilder<T>b)where T:class{b.Property<DateTimeOffset>("CreatedAtUtc").HasColumnName("created_at_utc");b.Property<DateTimeOffset>("UpdatedAtUtc").HasColumnName("updated_at_utc");b.Property<long>("Version").HasColumnName("version").IsConcurrencyToken();}
}
internal sealed class OrderConfiguration:IEntityTypeConfiguration<Order>{public void Configure(EntityTypeBuilder<Order>b){OrderConfig.Company(b,"orders");OrderConfig.Mutable(b);b.Property(x=>x.BranchId).HasColumnName("branch_id");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.OrderNumber).HasColumnName("order_number").HasMaxLength(40);b.Property(x=>x.Source).HasColumnName("source").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.ExternalReference).HasColumnName("external_reference").HasMaxLength(150);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.OrderDate).HasColumnName("order_date");b.Property(x=>x.RequestedDeliveryDate).HasColumnName("requested_delivery_date");b.Property(x=>x.SubmittedAtUtc).HasColumnName("submitted_at_utc");b.Property(x=>x.CancelledAtUtc).HasColumnName("cancelled_at_utc");b.Property(x=>x.CancellationReasonCode).HasColumnName("cancellation_reason_code").HasMaxLength(50);b.Property(x=>x.CancellationReasonText).HasColumnName("cancellation_reason_text").HasMaxLength(500);b.Property(x=>x.ShippingAddressSnapshotId).HasColumnName("shipping_address_snapshot_id");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.CancelledByUserId).HasColumnName("cancelled_by_user_id");b.HasOne<Branch>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.BranchId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Customer>().WithMany().HasForeignKey(x=>new{x.CustomerId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.OrderNumber}).HasFilter("order_number IS NOT NULL").IsUnique().HasDatabaseName("uq_orders_company_number");b.HasIndex(x=>new{x.CompanyId,x.Source,x.ExternalReference}).HasFilter("external_reference IS NOT NULL").IsUnique().HasDatabaseName("uq_orders_external_reference");b.HasIndex(x=>new{x.CompanyId,x.Status,x.CreatedAtUtc}).HasDatabaseName("ix_orders_status_created");b.HasIndex(x=>new{x.CompanyId,x.CustomerId}).HasDatabaseName("ix_orders_customer");b.HasIndex(x=>new{x.CompanyId,x.BranchId}).HasDatabaseName("ix_orders_branch");}}
internal sealed class OrderItemConfiguration:IEntityTypeConfiguration<OrderItem>{public void Configure(EntityTypeBuilder<OrderItem>b){OrderConfig.Company(b,"order_items");OrderConfig.Mutable(b);b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.LineNumber).HasColumnName("line_number");b.Property(x=>x.ProductId).HasColumnName("product_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");b.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,4);b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(1000);b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.SnapshotProductCode).HasColumnName("snapshot_product_code").HasMaxLength(50);b.Property(x=>x.SnapshotProductName).HasColumnName("snapshot_product_name").HasMaxLength(200);b.Property(x=>x.SnapshotVariantSku).HasColumnName("snapshot_variant_sku").HasMaxLength(80);b.Property(x=>x.SnapshotVariantDisplayName).HasColumnName("snapshot_variant_display_name").HasMaxLength(200);b.Property(x=>x.SnapshotSizeCode).HasColumnName("snapshot_size_code").HasMaxLength(50);b.Property(x=>x.SnapshotColorCode).HasColumnName("snapshot_color_code").HasMaxLength(50);b.Property(x=>x.SnapshotUomCode).HasColumnName("snapshot_uom_code").HasMaxLength(30);b.HasOne<Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Product>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProductVariant>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductId,x.ProductVariantId}).HasPrincipalKey(x=>new{x.CompanyId,x.ProductId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.OrderId,x.LineNumber}).IsUnique().HasDatabaseName("uq_order_items_line");}}
internal sealed class OrderPrintConfiguration:IEntityTypeConfiguration<OrderPrintOperation>{public void Configure(EntityTypeBuilder<OrderPrintOperation>b){OrderConfig.Company(b,"order_print_operations");OrderConfig.Mutable(b);b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.Sequence).HasColumnName("sequence");b.Property(x=>x.PrintPositionCode).HasColumnName("print_position_code").HasMaxLength(50);b.Property(x=>x.PrintMethodCode).HasColumnName("print_method_code").HasMaxLength(50);b.Property(x=>x.Width).HasColumnName("width").HasPrecision(12,3);b.Property(x=>x.Height).HasColumnName("height").HasPrecision(12,3);b.Property(x=>x.ArtworkVersionId).HasColumnName("artwork_version_id");b.Property(x=>x.FileVersionId).HasColumnName("file_version_id");b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(1000);b.Property(x=>x.IsActive).HasColumnName("is_active");b.HasOne<Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<OrderItem>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderItemId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ArtworkVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ArtworkVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<FileVersion>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.FileVersionId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.OrderItemId,x.Sequence}).HasFilter("is_active").IsUnique().HasDatabaseName("uq_order_print_sequence");}}
internal sealed class OrderAddressConfiguration:IEntityTypeConfiguration<OrderAddressSnapshot>{public void Configure(EntityTypeBuilder<OrderAddressSnapshot>b){OrderConfig.Company(b,"order_address_snapshots");OrderConfig.Mutable(b);b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.SourceCustomerAddressId).HasColumnName("source_customer_address_id");b.Property(x=>x.RecipientName).HasColumnName("recipient_name").HasMaxLength(200);b.Property(x=>x.RecipientPhone).HasColumnName("recipient_phone").HasMaxLength(32);b.Property(x=>x.CountryCode).HasColumnName("country_code").HasMaxLength(2);b.Property(x=>x.Province).HasColumnName("province").HasMaxLength(150);b.Property(x=>x.City).HasColumnName("city").HasMaxLength(150);b.Property(x=>x.District).HasColumnName("district").HasMaxLength(150);b.Property(x=>x.AddressLine1).HasColumnName("address_line1").HasMaxLength(500);b.Property(x=>x.AddressLine2).HasColumnName("address_line2").HasMaxLength(500);b.Property(x=>x.PostalCode).HasColumnName("postal_code").HasMaxLength(32);b.HasOne<Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<CustomerAddress>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SourceCustomerAddressId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.OrderId}).IsUnique();}}
internal sealed class OrderTimelineConfiguration:IEntityTypeConfiguration<OrderTimelineEvent>{public void Configure(EntityTypeBuilder<OrderTimelineEvent>b){OrderConfig.Company(b,"order_timeline_events");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.EventType).HasColumnName("event_type").HasMaxLength(50);b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");b.Property(x=>x.Summary).HasColumnName("summary").HasMaxLength(500);b.Property(x=>x.RelatedEntityId).HasColumnName("related_entity_id");b.HasOne<Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.CompanyId,x.OrderId,x.OccurredAtUtc,x.Id});}}
